# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


# ---
def make_student(last, first, section="A", email="x@example.edu"):
    return Student("id", last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_by_name(self):
        rows = contact_rows(
            [make_student("Varrow", "Ines"), make_student("Thistle", "Bram")]
        )
        self.assertTrue(rows[0].startswith("Thistle, Bram"))
        self.assertTrue(rows[1].startswith("Varrow, Ines"))

    def test_columns_line_up(self):
        rows = contact_rows(
            [
                make_student("Lee", "Al", "A", "al@example.edu"),
                make_student("Thistle", "Bram", "BB", "bt@example.edu"),
            ]
        )
        self.assertEqual(rows[0].index("al@"), rows[1].index("bt@"))
        self.assertEqual(rows[0], "Lee, Al        A   al@example.edu")

    def test_missing_email_names_the_student(self):
        with self.assertRaises(ProjectError) as caught:
            contact_rows([make_student("Quillon", "Sefa", email=None)])
        self.assertIn("Quillon, Sefa", str(caught.exception))

    def test_empty_email_text_counts_as_missing(self):
        with self.assertRaises(ProjectError):
            contact_rows([make_student("Quillon", "Sefa", email="")])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
